mapper.select:
SELECT TO_CHAR(PRI.VALUE_DATE,'YYYY-MM-DD') cDate,
/*净值型产品需要查询单位净值跟单位累计净值*/

         TO_CHAR(ROUND(NVL(PRI.UNIT_VALUE,0),4),'FM9999999999999990.0000') value,
   		 TO_CHAR(ROUND(NVL(PRI.UNIT_VALUE_T,0),4),'FM9999999999999990.0000') totalValue

/*现管型产品需要查询万份收益跟七日年化收益率*/

	to_char(ROUND(nvl(PRI.W_YIELD,0),4),'FM9999999999999990.0000') value,
	to_char(ROUND(nvl(PRI.YIELD_7,0) * 100,4),'FM9999999999999990.0000') totalValue

  FROM REP_PROD_INFO INFO
INNER JOIN REP_PROD_INDEX PRI ON PRI.PROD_ID = INFO.PROD_ID AND PRI.STATUS = 'E'
  WHERE INFO.PROD_ID = #{prodId}
	AND PRI.STATUS = 'E'
  	/*净值型产品需要查询工作日的净值数据*/

		AND EXISTS (
		SELECT 1 FROM CHB_MKT_HOLIDAY H WHERE H.MARKET_CODE = '04'
		AND H.IS_HOLIDAY = '0'
		AND PRI.VALUE_DATE = H.BUSI_DATE
		)



			#{item}


  ORDER BY PRI.VALUE_DATE DESC

SELECT * FROM (
	select h.busi_date from CHB_MKT_HOLIDAY h
	where h.busi_date <= to_date(#{busi_date},'yyyy-MM-dd')
	  and h.market_code = #{market_code}

		and h.is_holiday = #{is_holiday}

	order by h.busi_date desc
) WHERE ROWNUM <= 31
